// Opening language phases precede later inference operations. Stable IDs preserve assignments.
const openingOrder = ['orientation', 'sufficient-necessary', 'group-1', 'group-2', 'rules-facts'];
foundationUnits.sort((a, b) => {
  const left = openingOrder.indexOf(a.id);
  const right = openingOrder.indexOf(b.id);
  return (left < 0 ? openingOrder.length : left) - (right < 0 ? openingOrder.length : right);
});
